LIMIT 1000 OFFSET 2000;

-- DATABASE loja

CREATE TABLE TB_CARGO(
    cod_cargo VARCHAR (5) PRIMARY KEY,
    nome_cargo VARCHAR (60) NOT NULL,
    departamento VARCHAR (40) NOT NULL,
    piso_salarial DECIMAL (10,2) NOT NULL
);

CREATE TABLE TB_FUNCIONARIO(
  cod_funcionario VARCHAR (5) PRIMARY KEY,
  nome_funcionario VARCHAR (60) NOT NULL,
  cpf VARCHAR (14) NOT NULL UNIQUE,
  cod_cargo VARCHAR (5),
  salario DECIMAL (10,2),
  data_admissao DATE,
  data_desligamento DATE,
  status VARCHAR (10),
  motivo_desligamento VARCHAR (30),
  turno VARCHAR (8),
        FOREIGN KEY (cod_cargo)
        REFERENCES TB_CARGO(cod_cargo)
);

CREATE TABLE loja.TB_VENDEDOR(
  cod_vendedor VARCHAR (5) PRIMARY KEY,
  cod_funcionario VARCHAR (5) NOT NULL,
  nome_vendedor VARCHAR (60) NOT NULL,
  comissao_pct DECIMAL (4,2) NOT NULL,
  meta_mensal DECIMAL (10,2) NOT NULL,
    FOREIGN KEY (cod_funcionario)
    REFERENCES TB_FUNCIONARIO (cod_funcionario)
);

